const deskCoastalBounds=[-74.4,40.3,-66.8,45.2];
function deskCoastalXY(lat,lon){const [w,s,e,n]=deskCoastalBounds,scale=Math.min(1000/((e-w)*.76),540/(n-s)),dx=(1000-(e-w)*.76*scale)/2,dy=(540-(n-s)*scale)/2;return [dx+(lon-w)*.76*scale,dy+(n-lat)*scale];}
function deskLightColour(c){return {white:'#fff1c4',red:'#ff7069',green:'#79e6a8',yellow:'#ffe066',blue:'#8ec5ff'}[c]||'#fff1c4';}
// One period of the light: {P, layers:[{colour,on:[[t0,t1],...]}]}; null = fixed light.
function deskLightPattern(l){
 const [,,,ch,grp,col,per,seq]=l,cols=String(col||'white').split(';'),g=Math.max(1,grp||1);
 if(ch==='F')return null;
 let P=per||null,on=[];
 if(/^Al/.test(ch)&&cols.length>1){P=P||10;let f=/Fl/.test(ch)?(P>=10?1:.5):P/cols.length;const m=seq&&seq.match(/^\s*([\d.]+)/);if(m&&+m[1]>0)f=Math.max(.3,+m[1]);return {P,layers:cols.map((c,i)=>({colour:deskLightColour(c),on:[[i*P/cols.length,i*P/cols.length+f]]}))};}
 if(seq&&/^[\d.+()\s]+$/.test(seq)){let t=0;for(const part of seq.split('+')){const m=part.trim();const v=parseFloat(m.replace(/[()]/g,''));if(!m||isNaN(v))continue;if(m.startsWith('('))t+=v;else{on.push([t,t+v]);t+=v;}}P=P||t;}
 else if(ch==='Iso'){P=P||6;on=[[0,P/2]];}
 else if(ch==='Oc'){P=P||4;const ecl=Math.min(1,P/(2*g+1));let t=0;for(let i=0;i<g;i++){t+=ecl;on.push([t,i<g-1?t+ecl:P]);t+=ecl;}}
 else if(ch==='Q'||ch==='VQ'){P=P||(ch==='Q'?1:.5);on=[[0,P/2]];}
 else {P=P||6;const f=ch==='LFl'?2:(P>=10?1:.5);const gap=g>1?Math.max(.6,Math.min(2.2,(P/2-g*f)/(g-1))):0;for(let i=0;i<g;i++)on.push([i*(f+gap),i*(f+gap)+f]);}
 if(!P||!on.length)return null;
 on=on.map(([a,b])=>[a,Math.min(P,Math.max(b,a+.3))]);
 return {P,layers:[{colour:deskLightColour(cols[0]),on}]};
}
function deskLightKeyframes(name,P,on){
 const stops=new Map([[0,.06],[100,.06]]);const pct=t=>+(Math.max(0,Math.min(P,t))/P*100).toFixed(2);
 for(const [a,b] of on){if(a>0)stops.set(pct(a-.02),.06);stops.set(pct(a),1);stops.set(pct(b),1);if(b<P)stops.set(pct(b+.02),.06);}
 return '@keyframes '+name+'{'+[...stops].sort((x,y)=>x[0]-y[0]).map(([p,o])=>p+'%{opacity:'+o+'}').join('')+'}';
}
function deskLightLabel(l){const [,,,ch,grp,col,per,,rng]=l;const c=String(col||'white').split(';').map(x=>({white:'W',red:'R',green:'G',yellow:'Y',blue:'Bu'}[x]||x)).join('/');return ch+(grp>1?'('+grp+')':'')+' '+c+(per?' '+per+'s':'')+(rng?' · '+rng+' NM':'');}
function deskCoastalChart(){
 const v=seaboardViews.north;let css='',marks='',labels='',rotating=0;const placed=[];  // labels: brightest first (list is sorted by range), skip collisions
 DESK_LIGHTS.forEach((l,i)=>{
  const [x,y]=deskCoastalXY(l[1],l[2]),p=deskLightPattern(l),name=esc(l[0]);
  if(!p){const c=deskLightColour(String(l[5]).split(';')[0]);marks+='<g class="cl cl-fixed" fill="'+c+'"><title>'+name+' · '+esc(deskLightLabel(l))+'</title><circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="9" opacity=".12"/><circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="2.6" opacity=".85"/></g>';}
  else if(/^(Fl|LFl|Al\.Fl)$/.test(l[3])&&(l[8]||0)>=9){
   // Major flashing lights are drawn as a rotating optic: one beam per flash in the group,
   // one turn per charted period, reach equal to the charted nominal range (1 nm = 1.84 units).
   const X=x.toFixed(1),Y=y.toFixed(1),len=Math.max(20,(l[8]||10)*1.84),w=len*.15;rotating++;
   const beams=p.layers.map(L=>{const gid='clBeam'+({'#ff7069':'R','#79e6a8':'G'}[L.colour]||'W');return L.on.map(([t0])=>'<polygon transform="rotate('+(t0/p.P*360).toFixed(1)+' '+X+' '+Y+')" points="'+X+','+Y+' '+(x-w).toFixed(1)+','+(y-len).toFixed(1)+' '+(x+w).toFixed(1)+','+(y-len).toFixed(1)+'" fill="url(#'+gid+')"/>').join('');}).join('');
   marks+='<g class="cl cl-rot" fill="'+p.layers[0].colour+'"><title>'+name+' · '+esc(deskLightLabel(l))+'</title><g class="cl-spin" style="transform-origin:'+X+'px '+Y+'px;--per:'+p.P+'s;--delay:-'+((i*1.37)%p.P).toFixed(2)+'s">'+beams+'</g><circle cx="'+X+'" cy="'+Y+'" r="7" opacity=".16"/><circle cx="'+X+'" cy="'+Y+'" r="2.6"/></g>';
  }
  else{marks+='<g class="cl"><title>'+name+' · '+esc(deskLightLabel(l))+'</title>'+p.layers.map((L,k)=>{const id='cl'+i+'_'+k;css+=deskLightKeyframes(id,p.P,L.on)+'#spotBody .desk-coastal-native .'+id+'{animation:'+id+' '+p.P+'s linear infinite!important}';return '<g class="'+id+'" fill="'+L.colour+'"><circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="14" opacity=".14"/><circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="5" opacity=".55"/><circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="2.4"/></g>';}).join('')+'</g>';}
  if((l[8]||0)>=17&&!placed.some(([px,py])=>Math.abs(py-y)<13&&Math.abs(px-x)<150)){placed.push([x,y]);const right=l[2]>-70.2||l[1]<41.2;labels+='<text x="'+(x+(right?9:-9)).toFixed(1)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="'+(right?'start':'end')+'">'+esc(l[0].replace(/ Light$/,'').toUpperCase())+'</text>';}
 });
 return '<div class="desk-coastal-native"><style>'+css+'</style><svg viewBox="0 0 1000 540" preserveAspectRatio="xMidYMid meet" role="img" aria-label="New England coastal lights flashing at their charted rhythms"><defs>'+[['W','#fff1c4'],['R','#ff7069'],['G','#79e6a8']].map(([k,c])=>'<linearGradient id="clBeam'+k+'" x1=".5" y1="1" x2=".5" y2="0"><stop offset="0" stop-color="'+c+'" stop-opacity=".8"/><stop offset=".45" stop-color="'+c+'" stop-opacity=".3"/><stop offset="1" stop-color="'+c+'" stop-opacity="0"/></linearGradient>').join('')+'</defs><rect width="1000" height="540" fill="#060e16"/><path d="'+v.path+'" fill="#131f22" stroke="#4d665f" stroke-width=".6"/>'+marks+'<g class="cl-labels">'+labels+'</g><text class="cl-kicker" x="24" y="34">COASTAL LIGHTS</text><text class="cl-kicker-sub" x="24" y="52">NEW ENGLAND AFTER DARK · '+DESK_LIGHTS.length+' CHARTED LIGHTS · '+rotating+' SWEEP ONCE PER CHARTED PERIOD · BEAM REACH = CHARTED RANGE</text><text class="cl-ocean" x="975" y="515" text-anchor="end">ATLANTIC OCEAN</text></svg></div>';
}
function deskCoastalHTML(){
 const tide=S.tides?esc(S.tides):'Awaiting tide update';
 return '<section class="desk-coastal" aria-label="Coastal Lights"><div class="desk-coastal-map" id="deskCoastalMap">'+deskCoastalChart()+'</div><footer class="desk-coastal-footer"><div><strong>STAMFORD TIDE</strong><span id="deskCoastalTide">'+tide+'</span></div><div class="desk-coastal-feature" id="deskCoastalFeature" aria-live="off"></div><div class="desk-coastal-actions"><button id="deskArtImmersive" type="button" aria-pressed="false">Gallery view</button><span class="desk-coastal-credit"><a class="cl-credit-osm" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">Lights © OpenStreetMap contributors · coast Natural Earth</a><a class="cl-credit-live" href="https://mapped.earth/lighthouses/new-england" target="_blank" rel="noopener noreferrer">Live map by Aaron J. Becker · mapped.earth ↗</a></span></div></footer></section>';
}
let deskCoastalFeatureTimer=null;
async function deskCoastalCanLive(){
 if(deskCoastalCanLive.cached!=null)return deskCoastalCanLive.cached;
 let ok=false;try{ok=!!(navigator.gpu&&await navigator.gpu.requestAdapter());}catch(e){ok=false;}
 return deskCoastalCanLive.cached=ok;
}
function deskCoastalLive(){
 const host=$('deskCoastalMap');if(!host)return;
 host.querySelector('iframe')?.remove();
 if(!CFG.coastalLive)return;   // live mapped.earth layer is opt-in: a cross-origin frame cannot report a blank render
 if(!navigator.onLine||document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 deskCoastalCanLive().then(ok=>{
  if(!ok||!document.body.contains(host)||host.querySelector('iframe'))return;
  const frame=document.createElement('iframe');frame.title='New England lighthouse map by mapped.earth';
  frame.referrerPolicy='no-referrer';frame.setAttribute('sandbox','allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox');
  frame.src='https://mapped.earth/lighthouses/new-england';host.append(frame);host.closest('.desk-coastal')?.classList.add('desk-coastal-is-live');
 });
}
function deskCoastalMount(){
 const host=$('deskCoastalMap');if(!host)return;
 clearInterval(deskCoastalFeatureTimer);
 let n=Math.floor(Math.random()*DESK_LIGHTS.length);
 const feature=()=>{const el=$('deskCoastalFeature');if(!el){clearInterval(deskCoastalFeatureTimer);return;}const l=DESK_LIGHTS[n%DESK_LIGHTS.length];n++;el.innerHTML='<strong>NOW SHOWING</strong><b>'+esc(l[0])+'</b><span>'+esc(deskLightLabel(l))+'</span>';};
 feature();deskCoastalFeatureTimer=setInterval(feature,9000);
 let wasPaused=deskState.paused;
 $('deskArtImmersive').onclick=()=>{const on=document.body.classList.toggle('desk-art-immersive');if(on){wasPaused=deskState.paused;if(!deskState.paused)$('deskPause').click();}else if(!wasPaused&&deskState.paused)$('deskPause').click();$('deskArtImmersive').textContent=on?'Exit gallery':'Gallery view';$('deskArtImmersive').setAttribute('aria-pressed',String(on));deskFit();};
 deskCoastalLive();
}
// A removed iframe stops rendering when the scene advances. Hide also releases it.
document.addEventListener('visibilitychange',()=>{const host=$('deskCoastalMap');if(!host)return;if(document.hidden){host.querySelector('iframe')?.remove();host.closest('.desk-coastal')?.classList.remove('desk-coastal-is-live');}else deskCoastalLive();});
new MutationObserver(()=>{if(!$('deskCoastalMap'))document.body.classList.remove('desk-art-immersive');}).observe($('spotBody'),{childList:true});
if(location.hash==='#coastal')setTimeout(()=>deskJump('art','COASTAL LIGHTS'),1800);

setInterval(()=>{const tide=document.getElementById("deskCoastalTide");if(tide)tide.textContent=S.tides||"Awaiting tide update";},10000);

// Atlas presentation: preserve the complete source-driven page list and both wires.
function deskSceneFor(key){
 if(/COASTAL LIGHTS/.test(key))return 'coast';
 if(/AURORA/.test(key))return 'aurora';
 if(/MOON|NASA|SPACE OPS/.test(key))return 'sky';
 if(/EARTHQUAKE/.test(key))return 'seismic';
 if(/WORLD CLOCK/.test(key))return 'time';
 if(/WEATHER|7-DAY|RADAR/.test(key))return 'weather';
 if(/SOUND|LAKE|BUOY/.test(key))return 'water';
 if(/MARKETS|RATE|FED WATCH|BANKING|RIA|M&A/.test(key))return 'markets';
 if(/METRO|DRIVE|FLIGHTS/.test(key))return 'travel';
 if(/ART|PAINTING|WORD|HISTORY|GET IT DONE/.test(key))return 'culture';
 return 'editorial';
}
const atlasMediaOriginal=deskMedia;
deskMedia=function(){atlasMediaOriginal();const terminal=$('spotBody').querySelector('.tt-bar span');if(terminal)terminal.textContent='TECHNOLOGY & IDEAS';
 for(const row of $('spotBody').querySelectorAll('.st-r')){const record=row.querySelector('.wl')?.textContent.match(/(\d+)\D+(\d+)/);if(record){const wins=Number(record[1]),losses=Number(record[2]);if(wins+losses)row.style.setProperty('--win-pct',(wins/(wins+losses)*100)+'%');}}
 for(const foot of $('spotBody').querySelectorAll('.st-f'))foot.textContent='W–L · GB · BAR = WIN RATE';};

/* Coastal-style buoy chart: keep source geography and readings. */
const coastalBuoyChartOriginal=lisChartHTML;
lisChartHTML=function(){
 const host=document.createElement('div');host.innerHTML=coastalBuoyChartOriginal();
 const svg=host.querySelector('svg');if(!svg)return host.innerHTML;
 const ns='http://www.w3.org/2000/svg';
 svg.setAttribute('aria-label','Long Island Sound coastal lights and marine readings');
 svg.querySelectorAll('defs stop').forEach(s=>s.setAttribute('stop-color','#071117'));
 // Remove decorative soundings and traffic lanes; this is an ambient display.
 svg.querySelectorAll('g').forEach(g=>{if(g.getAttribute('fill')==='#2c4a66'||g.getAttribute('stroke')==='#8a5a9a')g.remove()});
 svg.querySelectorAll('path').forEach(p=>{if(p.getAttribute('fill')==='#0e2416'){p.setAttribute('fill','#182626');p.setAttribute('stroke','#54716b');p.setAttribute('stroke-width','.6')}else if(p.hasAttribute('stroke-dasharray'))p.remove()});
 svg.querySelectorAll('text').forEach(t=>{if(/TRAFFIC LANE|SOUNDINGS IN FEET/.test(t.textContent))t.remove()});
 svg.querySelectorAll('.buoy').forEach((g,i)=>{
  const core=g.querySelector('circle:last-child');const x=core.getAttribute('cx'),y=core.getAttribute('cy'),color=core.getAttribute('fill');
  g.setAttribute('class','coastal-buoy');g.style.setProperty('--delay',(-i*1.37)+'s');
  g.innerHTML=`<circle class="beacon-halo" cx="${x}" cy="${y}" r="15" fill="${color}" opacity=".06"/><circle class="beacon-halo" cx="${x}" cy="${y}" r="8" fill="${color}" opacity=".13"/><circle class="beacon-flash" cx="${x}" cy="${y}" r="3.4" fill="${color}"/><circle cx="${x}" cy="${y}" r="1.1" fill="#fff6d9"/>`;
 });
 const note=document.createElement('div');note.className='coastal-buoy-note';note.textContent='LONG ISLAND SOUND · AMBIENT CHART · LIGHT PATTERNS ILLUSTRATIVE';host.querySelector('.lis-map').append(note);
 return host.innerHTML;
};

