let seaboardRegion='sound';
function seaboardHTML(){
 const v=seaboardViews[seaboardRegion];
 return `<section class="seaboard"><div class="seaboard-toolbar"><h2>${v.title}<small>AFTER DARK · ${v.lights.length} HISTORIC LIGHT SITES</small></h2><div>${Object.entries(seaboardViews).map(([k,r])=>`<button data-seaboard="${k}" aria-pressed="${k===seaboardRegion}">${r.title}</button>`).join('')}</div></div><svg viewBox="0 0 1000 540" role="img" aria-label="${v.title}, nighttime lighthouse map"><rect width="1000" height="540" fill="#060e16"/><path d="${v.path}" fill="#19292c" stroke="#698880" stroke-width=".65"/>${v.lights.map(([x,y,name],i)=>`<g class="seaboard-light" style="--per:${4+i%7}s;--delay:-${i*.71}s"><title>${esc(name)}</title><circle cx="${x}" cy="${y}" r="9" fill="#ffdc91" opacity=".08"/><circle class="seaboard-pulse" cx="${x}" cy="${y}" r="3" fill="#ffe7af"/><circle cx="${x}" cy="${y}" r="1.1" fill="#fff6de"/></g>`).join('')}<text x="975" y="515" text-anchor="end" fill="#73908e" font-family="Georgia" font-size="18" letter-spacing="5">ATLANTIC OCEAN</text></svg><footer>Historic locations · illustrative night glow · not live operational status <span><a href="https://www.coast.noaa.gov/arcgis/rest/services/OceanReports/HistoricLighthouses/MapServer" target="_blank" rel="noopener">NOAA</a> · <a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">Natural Earth</a></span></footer></section>`;
}
function seaboardMount(){document.querySelectorAll('[data-seaboard]').forEach(b=>b.onclick=()=>{seaboardRegion=b.dataset.seaboard;const host=document.querySelector('.seaboard');if(host){host.outerHTML=seaboardHTML();seaboardMount()}})}

let seaboardDemoBoats=true;
let seaboardBoatTimer;
function seaboardColor(i){return ['#ffe6b0','#ffe6b0','#ff7b79','#8fe3ba','#ffe6b0'][i%5]}
function seaboardBoatLayer(){
 const bounds={sound:[-74.4,40.3,-69.7,42.25],north:[-74.4,40.3,-66.8,45.2],east:[-82,24,-66,46]}[seaboardRegion];
 const [w,s,e,n]=bounds,scale=Math.min(1000/((e-w)*.76),540/(n-s)),dx=(1000-(e-w)*.76*scale)/2,dy=(540-(n-s)*scale)/2;
 const now=Date.now();
 const samples=[{lon:-72.7,lat:41.05,cog:75,name:'Demo · Sound passage'},{lon:-71.5,lat:41.1,cog:115,name:'Demo · Block Island Sound'},{lon:-70.7,lat:40.8,cog:220,name:'Demo · Offshore passage'}];
 const reports=seaboardDemoBoats?samples:Object.values(S.ships||{}).filter(b=>Number.isFinite(b.lat)&&Number.isFinite(b.lon)&&now-b.ts<20*60000);
 const visible=reports.filter(b=>b.lon>=w&&b.lon<=e&&b.lat>=s&&b.lat<=n).slice(0,80);
 const marks=visible.map(b=>{const x=dx+(b.lon-w)*.76*scale,y=dy+(n-b.lat)*scale;return `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><title>${esc(b.name||'AIS vessel')}${seaboardDemoBoats?' · illustrative position':''}</title><circle r="12" fill="#74e4ef" opacity=".08"/><g transform="rotate(${Number.isFinite(b.cog)?b.cog:0})"><path d="M0 -8 L4.5 5 L0 3 L-4.5 5 Z" fill="#a5f1f4" stroke="#0a2029" stroke-width="1"/><path d="M0 8 L0 18" stroke="#74e4ef" stroke-width="1" opacity=".5"/></g></g>`}).join('');
 const label=seaboardDemoBoats?'DEMO BOATS · ILLUSTRATIVE POSITIONS':visible.length?`${visible.length} RECENT AIS REPORTS · SOUND COVERAGE`:CFG.aisKey?'NO RECENT AIS REPORTS IN VIEW · SOUND COVERAGE':'VESSELS · AIS NOT CONNECTED';
 return {marks,label};
}
function refreshSeaboardBoats(){const layer=document.querySelector('#seaboardBoats'),status=document.querySelector('#seaboardBoatStatus');if(!layer)return;const b=seaboardBoatLayer();layer.innerHTML=b.marks;if(status)status.textContent=b.label}
const seaboardColorOriginal=seaboardHTML;
seaboardHTML=function(){
 const host=document.createElement('div');host.innerHTML=seaboardColorOriginal();
 host.querySelectorAll('.seaboard-light').forEach((g,i)=>{const c=seaboardColor(i);g.querySelectorAll('circle').forEach((dot,j)=>{if(j<2)dot.setAttribute('fill',c)})});
 const svg=host.querySelector('svg'),layer=document.createElementNS('http://www.w3.org/2000/svg','g');layer.id='seaboardBoats';layer.innerHTML=seaboardBoatLayer().marks;svg.append(layer);
 const rail=document.createElement('div');rail.className='seaboard-boat-rail';rail.innerHTML=`<span id="seaboardBoatStatus">${seaboardBoatLayer().label}</span><button id="seaboardDemoToggle" aria-pressed="${seaboardDemoBoats}">${seaboardDemoBoats?'Hide demo boats':'Preview demo boats'}</button>`;svg.after(rail);
 host.querySelector('footer').firstChild.textContent='Historic sites · illustrative colors and glow ';
 return host.innerHTML;
};
const seaboardBoatsMountOriginal=seaboardMount;
seaboardMount=function(){
 seaboardBoatsMountOriginal();clearInterval(seaboardBoatTimer);
 const b=document.querySelector('#seaboardDemoToggle');if(b)b.onclick=()=>{seaboardDemoBoats=!seaboardDemoBoats;b.setAttribute('aria-pressed',String(seaboardDemoBoats));b.textContent=seaboardDemoBoats?'Hide demo boats':'Preview demo boats';refreshSeaboardBoats()};
 seaboardBoatTimer=setInterval(()=>{if(!document.querySelector('#seaboardBoats')){clearInterval(seaboardBoatTimer);return}refreshSeaboardBoats()},10000);
};

